import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Volltextsuche","description":"","frontmatter":{},"headers":[],"relativePath":"de/advanced/search.md","filePath":"de/advanced/search.md","lastUpdated":1784903584000}'),i={name:"de/advanced/search.md"};function d(r,e,l,o,c,h){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="volltextsuche" tabindex="-1">Volltextsuche <a class="header-anchor" href="#volltextsuche" aria-label="Permalink to &quot;Volltextsuche&quot;">​</a></h1><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><p>swag2mcp enthält eine integrierte Volltext-Suchmaschine (bluge), die alle Endpunkte aller Specs indiziert. Der LLM kann nach Endpunkten nach Methode, Pfad, Zusammenfassung oder Tag suchen — sogar ohne die Endpunkt-ID zu kennen.</p><h2 id="wie-die-indizierung-funktioniert" tabindex="-1">Wie die Indizierung funktioniert <a class="header-anchor" href="#wie-die-indizierung-funktioniert" aria-label="Permalink to &quot;Wie die Indizierung funktioniert&quot;">​</a></h2><p>Wenn eine Spec hinzugefügt oder aktualisiert wird, wird jeder Endpunkt indiziert. Die folgenden Felder sind durchsuchbar:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Beschreibung</th><th>Beispiel</th></tr></thead><tbody><tr><td><code>method</code></td><td>HTTP-Methode</td><td><code>GET</code>, <code>POST</code>, <code>PUT</code></td></tr><tr><td><code>path</code></td><td>API-Endpunkt-Pfad</td><td><code>/api/v1/users/{id}</code></td></tr><tr><td><code>summary</code></td><td>OpenAPI-Zusammenfassung</td><td>&quot;Find pet by ID&quot;</td></tr><tr><td><code>tag</code></td><td>Endpunkt-Kategorie</td><td>&quot;pets&quot;, &quot;users&quot;</td></tr><tr><td><code>_all</code></td><td>Alle Felder kombiniert</td><td>method + path + tag + summary</td></tr></tbody></table><p>Der Index wird bei jedem MCP-Server-Neustart neu aufgebaut. Er wird für schnelle Suchvorgänge im Speicher gehalten.</p><h2 id="abfragesyntax" tabindex="-1">Abfragesyntax <a class="header-anchor" href="#abfragesyntax" aria-label="Permalink to &quot;Abfragesyntax&quot;">​</a></h2><p>Die Suche unterstützt eine umfangreiche Abfragesyntax für präzises Filtern:</p><table tabindex="0"><thead><tr><th>Beispiel</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>pet</code></td><td>Einfache Textsuche über alle Felder</td></tr><tr><td><code>method:GET</code></td><td>Alle GET-Endpunkte finden</td></tr><tr><td><code>tag:pets</code></td><td>Endpunkte im Tag &quot;pets&quot; finden</td></tr><tr><td><code>path:&quot;/api/v1/users&quot;</code></td><td>Exakte Pfadübereinstimmung</td></tr><tr><td><code>+method:POST +tag:pet</code></td><td>Beide Bedingungen müssen zutreffen</td></tr><tr><td><code>-method:DELETE</code></td><td>DELETE-Methoden ausschließen</td></tr><tr><td><code>create~</code></td><td>Unscharfe Suche (toleriert Tippfehler)</td></tr><tr><td><code>cr*</code></td><td>Platzhaltersuche</td></tr><tr><td><code>&quot;find pet&quot;</code></td><td>Phrasensuche</td></tr><tr><td><code>+summary:pet -method:DELETE</code></td><td>&quot;pet&quot; in Zusammenfassung einschließen, DELETE ausschließen</td></tr></tbody></table><h3 id="feldspezifische-suche" tabindex="-1">Feldspezifische Suche <a class="header-anchor" href="#feldspezifische-suche" aria-label="Permalink to &quot;Feldspezifische Suche&quot;">​</a></h3><p>Sie können innerhalb bestimmter Felder mit der Syntax <code>field:value</code> suchen:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method:GET</span></span>
<span class="line"><span>tag:pets</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span>summary:&quot;find pet by status&quot;</span></span></code></pre></div><h3 id="boolesche-operatoren" tabindex="-1">Boolesche Operatoren <a class="header-anchor" href="#boolesche-operatoren" aria-label="Permalink to &quot;Boolesche Operatoren&quot;">​</a></h3><ul><li><code>+</code> — der Begriff muss übereinstimmen (AND)</li><li><code>-</code> — der Begriff darf nicht übereinstimmen (NOT)</li><li>Leerzeichen zwischen Begriffen — OR (jeder Begriff kann übereinstimmen)</li></ul><h3 id="unscharfe-suche-und-platzhalter" tabindex="-1">Unscharfe Suche und Platzhalter <a class="header-anchor" href="#unscharfe-suche-und-platzhalter" aria-label="Permalink to &quot;Unscharfe Suche und Platzhalter&quot;">​</a></h3><ul><li><code>term~</code> — unscharfe Suche (findet ähnliche Wörter, behandelt Tippfehler)</li><li><code>te*</code> — Platzhalter (passt auf beliebige Zeichen)</li><li><code>te?t</code> — Einzelzeichen-Platzhalter</li></ul><h2 id="beispiele" tabindex="-1">Beispiele <a class="header-anchor" href="#beispiele" aria-label="Permalink to &quot;Beispiele&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Alle GET-Anfragen finden</span></span>
<span class="line"><span>method:GET</span></span>
<span class="line"><span></span></span>
<span class="line"><span># POST-Anfragen im Tag &quot;pet&quot; finden</span></span>
<span class="line"><span>+method:POST +tag:pet</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Endpunkte nach exaktem Pfad finden</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Nach Beschreibung finden</span></span>
<span class="line"><span>&quot;find pet by status&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Alles außer DELETE finden</span></span>
<span class="line"><span>+summary:pet -method:DELETE</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Unscharfe Suche nach &quot;create&quot; (behandelt Tippfehler)</span></span>
<span class="line"><span>create~</span></span></code></pre></div><h2 id="mcp-tool" tabindex="-1">MCP-Tool <a class="header-anchor" href="#mcp-tool" aria-label="Permalink to &quot;MCP-Tool&quot;">​</a></h2><p>Das <code>search</code>-MCP-Tool stellt die Suchmaschine dem LLM zur Verfügung:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ search(query: &quot;find pet by status&quot;, limit: 5)</span></span>
<span class="line"><span>← GET /pet/findByStatus — Findet Haustiere nach Status</span></span>
<span class="line"><span>   GET /pet/{petId} — Haustier nach ID finden</span></span></code></pre></div><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to &quot;Parameter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Erforderlich</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>query</code></td><td>Ja</td><td>Suchabfrage (unterstützt strukturierte Syntax)</td></tr><tr><td><code>limit</code></td><td>Ja</td><td>Maximale Ergebnisse (1-50)</td></tr></tbody></table><h2 id="wichtige-hinweise" tabindex="-1">Wichtige Hinweise <a class="header-anchor" href="#wichtige-hinweise" aria-label="Permalink to &quot;Wichtige Hinweise&quot;">​</a></h2><ul><li><strong>Der Index ist im Speicher</strong> — er wird bei jedem Start des MCP-Servers neu aufgebaut. Es gibt keine persistente Indexdatei.</li><li><strong>Alle Felder werden kleingeschrieben</strong> — die Suche ist nicht case-sensitive</li><li><strong>Limit ist auf 50 begrenzt</strong> — Sie können nicht mehr als 50 Ergebnisse anfordern</li><li><strong>Ungültige Abfragesyntax</strong> gibt eine hilfreiche Fehlermeldung mit Beispielen zurück</li><li><strong>Das Feld <code>_all</code></strong> kombiniert Methode, Pfad, Tag und Zusammenfassung für einfache Textsuche</li></ul>`,26)])])}const f=t(i,[["render",d]]);export{u as __pageData,f as default};
